sources.stylesheets/components/_navbar.scss:
@import "./variables.scss";
@import "./mixins.scss";

.navbar {
  background-color: $muddy-brown;
  color: $main-white; //    height: 50px;
  height: 100%;
  min-height: 50px;
  padding: 0;
  position: relative;
  .navbar-brand img {
    position: absolute;
    top: 50px;
    left: 48%;
    transform: translate(-50%, -50%);
    height: 128px;
    width: 128px;
    z-index: 1;
  }
  ul {
    min-width: 100%;
    display: table;
    table-layout: fixed; /* the magic dust that ensures equal width */
  }
  li {
    min-height: 100%;
    display: table-cell;
    text-align: center;
  }
  li:nth-of-type(3), li:nth-of-type(4), li:nth-of-type(7) {
    text-align: left;
    min-width: 50px;

  }
  li:nth-of-type(5),
  li:nth-of-type(1) {
    text-align: right;
  }
  li:nth-of-type(5) {
      min-width: 50px;
  }
  a, .nav-link {
    font: $sub-header;
    font-size: 1em;
    text-transform: uppercase;
    letter-spacing: 0.3em;
    color: white;
  }
}

